#include <zephyr/sys/sem.h>
#include <zephyr/sys/atomic.h>

#ifdef CONFIG_USERSPACE
static inline struct k_futex *sem_to_futex(struct sys_sem *sem)
{
	return &sem->futex;
}

static inline atomic_t *sem_to_atomic(struct sys_sem *sem)
{
	return &sem->futex.val;
}
#else
static inline struct k_sem *sem_to_k_sem(struct sys_sem *sem)
{
	return &sem->kernel_sem;
}
#endif

/*
 * Look like atomic_get(), concurrency control without initial checking
 * and read it again to check if the value is greater than positive 1.
 * Otherwise, return the status of atomic_cas().
 */
static inline bool atomic_dec_positive_or_zero(atomic_t *target,
					       atomic_val_t limit)
{
	atomic_val_t old_value;
	atomic_val_t old_next;

	old_value = atomic_get(target);

	while (old_value > 0) {
		old_next = old_value - 1;
		if (atomic_cas(target, old_value, old_next)) {
			return true;
		}

		old_value = atomic_get(target);
	}

	return false;
}

/*
 * Look like atomic_get(), concurrency control without initial checking
 * and read it again to check if the value is less than the limit.
 * Otherwise, return the status of atomic_cas().
 */
static inline int atomic_inc_limit(atomic_t *target, atomic_val_t limit)
{
	atomic_val_t old_value;
	atomic_val_t old_next;

	old_value = atomic_get(target);

	while (old_value < limit) {
		old_next = old_value + 1;
		if (atomic_cas(target, old_value, old_next)) {
			return old_value;
		}

		old_value = atomic_get(target);
	}

	return -EAGAIN;
}

int sys_sem_init(struct sys_sem *sem, unsigned int initial_count,
		 unsigned int limit)
{
	if ((sem == NULL) || (limit == 0U) || (initial_count > limit) ||
	    (limit > INT_MAX)) {
		return -EINVAL;
	}

#ifdef CONFIG_USERSPACE
	atomic_set(sem_to_atomic(sem), initial_count);
	sem->limit = limit;
#else
	(void)k_sem_init(sem_to_k_sem(sem), initial_count, limit);
#endif

	return 0;
}

int sys_sem_give(struct sys_sem *sem)
{
	int ret = 0;

#ifdef CONFIG_USERSPACE
	ret = atomic_inc_limit(sem_to_atomic(sem), sem->limit);
	if (ret >= 0) {
		ret = k_futex_wake(sem_to_futex(sem), false);
		if (ret > 0) {
			return 0;
		}
	}
#else
	k_sem_give(sem_to_k_sem(sem));
#endif
	return ret;
}

int sys_sem_take(struct sys_sem *sem, k_timeout_t timeout)
{
	int ret = 0;

#ifdef CONFIG_USERSPACE
	/*
	 * Check the atomic value, if it is greater than 1, decrement it
	 * and return the status.
	 */
	do {
		if (atomic_dec_positive_or_zero(sem_to_atomic(sem),
						sem->limit)) {
			return 0;
		}

		ret = k_futex_wait(sem_to_futex(sem), 0, timeout);
	} while (ret == 0 || ret == -EAGAIN);
#else
	ret = k_sem_take(sem_to_k_sem(sem), timeout);
	if (ret == -EBUSY) {
		ret = -ETIMEDOUT;
	}
#endif
	return ret;
}

unsigned int sys_sem_count_get(struct sys_sem *sem)
{
#ifdef CONFIG_USERSPACE
	int value = atomic_get(sem_to_atomic(sem));

	return (value > 0) ? value : 0;
#else
	return k_sem_count_get(sem_to_k_sem(sem));
#endif
}
